<script setup lang="ts">
import {ref,watch} from 'vue'
import {ApiError} from '@/api/client'
import SiteDialog from '@/features/management-shared/SiteDialog.vue'
import {getTeacherAccountManagementApi,type CourseClassManagement,type CourseStudentImportPreview,type StudentImportJob} from '@/features/teacher-account-management/api'
import type {AdminRow} from './api'
const props=defineProps<{row?:AdminRow}>(),emit=defineEmits<{close:[];changed:[]}>(),api=getTeacherAccountManagementApi()
const data=ref<CourseClassManagement>(),error=ref(''),busy=ref(false),mode=ref('members'),student=ref(0),target=ref(0),name=ref(''),number=ref(''),token=ref(''),file=ref<File>(),preview=ref<CourseStudentImportPreview>(),job=ref<StudentImportJob>()
const cid=()=>Number(props.row?.course_id),gid=()=>Number(props.row?.id)
async function load(){if(!props.row)return;try{data.value=await api.management(cid(),gid())}catch(e){error.value=(e as Error).message}}
watch(()=>props.row,()=>{data.value=undefined;error.value='';mode.value='members';preview.value=undefined;job.value=undefined;void load()},{immediate:true})
async function run(action:()=>Promise<unknown>,back=true){busy.value=true;error.value='';try{await action();if(back)mode.value='members';await load();emit('changed')}catch(e){error.value=(e as Error).message;if(e instanceof ApiError&&e.fields.confirmation_token)token.value=String(e.fields.confirmation_token)}finally{busy.value=false}}
function chooseFile(e:Event){file.value=(e.target as HTMLInputElement).files?.[0];preview.value=undefined}
async function importPreview(){const body=new FormData();if(file.value)body.append('file',file.value);await run(async()=>{preview.value=await api.previewCourseImport(cid(),gid(),body)},false)}
async function confirmImport(){if(!preview.value)return;await run(async()=>{job.value=await api.confirmCourseImport(cid(),gid(),{preview_id:preview.value!.preview_id,class_state_token:preview.value!.class_state_token});preview.value=undefined},false)}
</script>
<template>
  <SiteDialog :open="Boolean(row)" :title="row?.name||'班级管理'" :subtitle="row?.course_name" wide @close="emit('close')">
    <p v-if="!data&&!error" role="status">正在加载班级成员…</p><template v-if="data">
      <div class="tabs"><button :class="{active:mode==='members'}" @click="mode='members'">成员名册</button><button v-if="data.capabilities.can_update" :class="{active:mode==='edit'}" @click="mode='edit'">班级设置</button><button v-if="data.capabilities.can_add_students" :class="{active:mode==='add'}" @click="mode='add';token=''">添加学生</button><button v-if="data.capabilities.can_add_students" :class="{active:mode==='import'}" @click="mode='import'">批量导入</button></div>
      <div v-if="mode==='members'" class="table-scroll"><table><thead><tr><th>姓名</th><th>学号</th><th>操作</th></tr></thead><tbody><tr v-for="entry in data.enrollments" :key="entry.enrollment_id"><td>{{ entry.student.display_name }}</td><td>{{ entry.student.student_number }}</td><td><button v-if="data.capabilities.can_move_students" class="link" @click="student=entry.student.id;mode='move';target=0">调班</button><button v-if="data.capabilities.can_remove_students" class="link danger" @click="student=entry.student.id;name=entry.student.display_name;mode='remove'">移除选课</button></td></tr><tr v-if="!data.enrollments.length"><td colspan="3" class="empty">暂无选课学生。</td></tr></tbody></table></div>
      <form v-if="mode==='edit'" id="class-edit" class="form-grid" @submit.prevent="run(()=>api.updateManagement(cid(),gid(),data!.class_group))"><label class="field">班级名称<input v-model="data.class_group.name" required></label><label class="field">年级<input v-model="data.class_group.academic_year" required pattern="[0-9]{4}"></label><label><input v-model="data.class_group.is_active" type="checkbox"> 启用班级</label></form>
      <form v-if="mode==='add'" id="class-add" class="form-grid" @submit.prevent="run(()=>api.manualEnrollment(cid(),gid(),{student_number:number,display_name:name,...(token?{confirmation_token:token}:{})}))"><label class="field">学号<input v-model="number" required></label><label class="field">姓名<input v-model="name" required></label><p class="hint">已有账号由服务端识别复用；跨班级转入需要再次确认。</p></form>
      <form v-if="mode==='move'" id="class-move" class="form-grid" @submit.prevent="run(()=>api.moveStudent(cid(),gid(),student,target))"><label class="field">目标班级<select v-model="target" required><option :value="0" disabled>选择本课程班级</option><option v-for="c in data.target_classes" :key="c.id" :value="c.id">{{ c.display_name || c.name }}</option></select></label><p>调班更新当前选课关系，既有正式任务和历史作答不会随之改写。</p></form><div v-if="mode==='remove'"><p>确认移除 {{ name }} 的当前班级选课关系？账号与历史任务保留。</p></div>
      <div v-if="mode==='import'" class="form-grid"><a class="management-text-link" :href="data.actions.import_template_url">下载导入模板</a><label class="field">学生名单文件<input type="file" accept=".csv,.xlsx" @change="chooseFile"></label><button :disabled="busy||!file" @click="importPreview">预览导入</button><div v-if="preview" class="table-scroll"><table><thead><tr><th>姓名</th><th>学号</th><th>选课处理</th></tr></thead><tbody><tr v-for="item in preview.preview" :key="item.student_number"><td>{{ item.display_name }}</td><td>{{ item.student_number }}</td><td>{{ {create:'新增选课',transfer:'从 '+item.source_class_name+' 转入',skip:'保留现有选课'}[item.enrollment_action] }}</td></tr></tbody></table><button class="primary" :disabled="busy" @click="confirmImport">确认导入 {{ preview.preview.length }} 行</button></div><div v-if="job" role="status"><p>导入任务 {{ job.job_id }} · {{ job.status }} · {{ job.processed_rows }} / {{ job.total_rows }}</p><p v-if="job.error_message" class="error-block">{{ job.error_message }}</p><button @click="run(async()=>{job=await api.courseImportJob(cid(),gid(),job!.job_id)},false)">刷新导入进度</button></div></div>
    </template><p v-if="error" role="alert" class="error-block">{{ error }}</p><template #footer><button @click="emit('close')">关闭</button><button v-if="['edit','add','move'].includes(mode)" class="primary" type="submit" :form="'class-'+mode" :disabled="busy">{{ busy?'正在保存…':'确认保存' }}</button><button v-if="mode==='remove'" class="danger" :disabled="busy" @click="run(()=>api.removeStudent(cid(),gid(),student))">确认移除</button></template>
  </SiteDialog>
</template>
